def _resolve_display_timezone(spec):
    raw = str(spec or "PST").strip() or "PST"
    upper = raw.upper()
    canonical = _TIMEZONE_ALIASES.get(upper, raw)
    try:
        tz = ZoneInfo(canonical)
        return tz, canonical
    except Exception:
        logging.warning(
            "Invalid timezone %r; falling back to America/Los_Angeles (PST)", raw
        )
        return ZoneInfo("America/Los_Angeles"), "America/Los_Angeles"


DISPLAY_TZ, DISPLAY_TZ_IANA = _resolve_display_timezone(DISPLAY_TIMEZONE_SETTING)


def as_display_tz(value=None):
    if value is None:
        dt = datetime.now(timezone.utc)
    elif isinstance(value, str):
        parsed = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
        dt = (
            parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=timezone.utc)
        )
    elif isinstance(value, datetime):
        dt = value if value.tzinfo is not None else value.replace(tzinfo=timezone.utc)
    else:
        raise TypeError("Timestamp must be a datetime, ISO string, or None")
    return dt.astimezone(DISPLAY_TZ)


def display_tz_abbr(dt=None):
    target = as_display_tz(dt)
    abbr = target.tzname()
    return abbr or DISPLAY_TIMEZONE_SETTING.upper() or DISPLAY_TZ_IANA


def format_display_ts(value=None, fmt="%Y-%m-%d %H:%M:%S %Z"):
    return as_display_tz(value).strftime(fmt)


def format_display_iso(value=None):
    return as_display_tz(value).isoformat()


class TzFormatter(logging.Formatter):
    """Logging formatter emitting %(asctime)s in the configured DISPLAY_TZ."""

    def formatTime(self, record, datefmt=None):
        dt = datetime.fromtimestamp(record.created, DISPLAY_TZ)
        if datefmt:
            return dt.strftime(datefmt)
        return f"{dt.strftime('%Y-%m-%d %H:%M:%S')},{int(record.msecs):03d}"


def _reconfigure_logging_timezone():
    fmt = TzFormatter("%(asctime)s %(levelname)s %(message)s")
    root = logging.getLogger()
    for h in root.handlers:
        h.setFormatter(fmt)
    for name, lgr in list(logging.Logger.manager.loggerDict.items()):
        if not isinstance(lgr, logging.Logger):
            continue
        if name.endswith(".minute_summary"):
            continue
        if name.startswith("rsi."):
            for h in lgr.handlers:
                h.setFormatter(fmt)


logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s",
)
_reconfigure_logging_timezone()


def make_logger(provider, symbol):
    logger = logging.getLogger(f"rsi.{RUN_ID}.{provider}.{symbol}")
    logger.setLevel(logging.INFO)
    logger.propagate = False
    if logger.handlers:
        return logger
    safe = "".join(c if c.isalnum() or c in "-_." else "_" for c in symbol)
    directory = LOG_ROOT / provider.lower()
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / f"{safe}-{provider}-{RUN_ID}.log"
    handler = logging.FileHandler(path, encoding="utf-8")
    handler.setFormatter(TzFormatter("%(asctime)s %(levelname)s %(message)s"))
    logger.addHandler(handler)
    logging.info("%s %s log: %s", provider, symbol, path)
    return logger


def normalized_time(value):
    if not isinstance(value, datetime):
        raise TypeError("Timestamp must be a datetime")
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError("Timestamp must be timezone-aware")
    return value.astimezone(MARKET_TZ)


def positive_price(value):
    if isinstance(value, bool):
        raise ValueError("Price must not be boolean")
    price = float(value)
    if not math.isfinite(price) or price <= 0:
        raise ValueError("Price must be finite and positive")
    return price


def regular_session(timestamp):
    value = as_utc(timestamp)
    bounds = session_bounds(value.astimezone(MARKET_TZ).date())
    return bounds is not None and bounds[0] <= value < bounds[1]


def extended_bounds(day):
    """Return (04:00 ET in UTC, 20:00 ET in UTC) for a valid NYSE trading day."""
    if session_bounds(day) is None:
        return None
    ext_open = as_utc(datetime.combine(day, EXTENDED_OPEN_TIME, tzinfo=MARKET_TZ))
    ext_close = as_utc(datetime.combine(day, EXTENDED_CLOSE_TIME, tzinfo=MARKET_TZ))
    return (ext_open, ext_close)


def extended_session(timestamp):
    """Return True if timestamp falls within NYSE extended trading hours (04:00–20:00 ET) on a trading day."""
    value = as_utc(timestamp)
    bounds = extended_bounds(value.astimezone(MARKET_TZ).date())
    return bounds is not None and bounds[0] <= value < bounds[1]


def session_allowed(timestamp):
    """Return True if bar timestamp matches configured RSI_SESSION_MODE (extended or regular)."""
    if RSI_SESSION_MODE == "extended":
        return extended_session(timestamp)
    return regular_session(timestamp)


def parse_local(value):
    result = datetime.fromisoformat(value)
    if result.tzinfo is None:
        result = result.replace(tzinfo=MARKET_TZ)
    return normalized_time(result)


